<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;

class HaccpExtendedController extends Controller
{
    private function admin(Request $r): void { abort_unless($r->user()?->access_role === 'admin', 403); }
    public function index(){return response()->json(['device_types'=>DB::table('haccp_device_types')->orderBy('name')->get(),'cleaning_plans'=>DB::table('haccp_cleaning_plans')->orderBy('name')->get()]);}
    public function storeDeviceType(Request $r){$this->admin($r);$d=$r->validate(['name'=>'required|string|max:120|unique:haccp_device_types,name','unit'=>'nullable|string|max:20','default_min_value'=>'nullable|numeric','default_max_value'=>'nullable|numeric','default_frequency'=>'nullable|string|max:40','default_interval_value'=>'nullable|integer|min:1','active'=>'boolean']);$id=DB::table('haccp_device_types')->insertGetId([...$d,'active'=>$d['active']??true,'created_at'=>now(),'updated_at'=>now()]);return response()->json(DB::table('haccp_device_types')->find($id),201);}
    public function updateDeviceType(Request $r,int $id){$this->admin($r);$d=$r->validate(['name'=>['required','string','max:120',Rule::unique('haccp_device_types','name')->ignore($id)],'unit'=>'nullable|string|max:20','default_min_value'=>'nullable|numeric','default_max_value'=>'nullable|numeric','default_frequency'=>'nullable|string|max:40','default_interval_value'=>'nullable|integer|min:1','active'=>'boolean']);DB::table('haccp_device_types')->where('id',$id)->update([...$d,'updated_at'=>now()]);return response()->json(DB::table('haccp_device_types')->find($id));}
    public function goodsReceipt(Request $r){$d=$r->validate(['supplier'=>'nullable|string|max:160','item'=>'required|string|max:255','visual_ok'=>'required|boolean','olfactory_ok'=>'required|boolean','supplier_docs_complete'=>'required|boolean','temperature'=>'nullable|numeric','notes'=>'nullable|string']);$id=DB::table('haccp_goods_receipts')->insertGetId([...$d,'completed_by'=>$r->user()->id,'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['id'=>$id],201);}
    public function retentionSample(Request $r){$d=$r->validate(['product'=>'required|string|max:255','batch'=>'nullable|string|max:120','produced_at'=>'nullable|date','sampled_at'=>'required|date','label'=>'nullable|string|max:160','storage_location'=>'nullable|string|max:160','dispose_on'=>'nullable|date','notes'=>'nullable|string']);$id=DB::table('haccp_retention_samples')->insertGetId([...$d,'recorded_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['id'=>$id],201);}
    public function completeFoodSample(Request $r,int $id){$d=$r->validate(['dish'=>'required|string|max:255','core_temperature'=>'required|numeric','sensory_ok'=>'required|boolean','notes'=>'nullable|string']);DB::table('haccp_food_samples')->where('id',$id)->where('status','open')->update([...$d,'completed_by'=>$r->user()->id,'completed_at'=>now(),'status'=>'completed','updated_at'=>now()]);return response()->noContent();}
    public function storeCleaningPlan(Request $r){$this->admin($r);$d=$r->validate(['name'=>'required|string|max:160','location'=>'nullable|string|max:160','activity'=>'required|string','cleaning_agent'=>'nullable|string|max:160','disinfectant'=>'nullable|string|max:160','haccp_role_id'=>'nullable|exists:haccp_roles,id','frequency'=>['required',Rule::in(['daily','weekly','monthly','interval'])],'schedule'=>'nullable|array','active'=>'boolean']);$d['schedule']=isset($d['schedule'])?json_encode($d['schedule']):null;$id=DB::table('haccp_cleaning_plans')->insertGetId([...$d,'active'=>$d['active']??true,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['id'=>$id],201);}
    public function completeCleaning(Request $r,int $id){$rec=DB::table('haccp_cleaning_records')->find($id);abort_unless($rec,404);abort_if($rec->completed_at,422,'Reinigung bereits dokumentiert.');$d=$r->validate(['notes'=>'nullable|string']);DB::table('haccp_cleaning_records')->where('id',$id)->update(['completed_by'=>$r->user()->id,'completed_at'=>now(),'notes'=>$d['notes']??null,'updated_at'=>now()]);return response()->noContent();}
}
